import{_ as o,o as d,c as t,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"内置工具","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md"}'),c={name:"guide/tools.md"};function l(i,e,r,s,n,h){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to &quot;内置工具&quot;">​</a></h1><p>工具是模型与外部世界交互的方式：读文件、搜索、执行命令、修改文件、向你提问、派出子代理。这一页逐个说明 nek 的内置工具，让你知道模型每一步在做什么，以及如何启用或限制它们。</p><h2 id="默认启用哪些工具" tabindex="-1">默认启用哪些工具 <a class="header-anchor" href="#默认启用哪些工具" aria-label="Permalink to &quot;默认启用哪些工具&quot;">​</a></h2><p>新会话默认启用：</p><ul><li>文件与搜索：<code>read</code>、<code>bash</code>、<code>edit</code>、<code>write</code>、<code>grep</code>、<code>find</code>、<code>ls</code>、<code>ast_grep</code>、<code>web_search</code>；</li><li>nek 扩展提供的：<code>todo_write</code>、<code>switch_mode</code>、<code>create_plan</code>、<code>update_plan</code>、<code>ask_question</code>、<code>subagent</code>、<code>await</code>；</li><li>按需出现的：<code>tool_search</code>（存在延迟加载的工具时，例如 MCP 工具）、MCP 资源工具。</li></ul><p><code>powershell</code> 默认不启用，需要在 Windows 上手动开启，见 <a href="/nekcode/platform/windows#powershell">在 Windows 上运行</a>。</p><h3 id="调整工具集" tabindex="-1">调整工具集 <a class="header-anchor" href="#调整工具集" aria-label="Permalink to &quot;调整工具集&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>作用</th></tr></thead><tbody><tr><td>设置 <code>defaultTools</code></td><td>替换启动时启用的内置工具列表。空数组表示不启用任何内置工具（扩展工具不受影响）</td></tr><tr><td><code>--tools a,b,c</code>（<code>-t</code>）</td><td>只启用列出的工具（内置、扩展、自定义工具都受限）。nek 的工具也必须列出才会出现</td></tr><tr><td><code>--exclude-tools a,b</code>（<code>-xt</code>）</td><td>在其他选择之后再禁用列出的工具</td></tr><tr><td><code>--no-builtin-tools</code>（<code>-nbt</code>）</td><td>禁用默认内置工具，保留扩展和自定义工具</td></tr><tr><td><code>--no-tools</code>（<code>-nt</code>）</td><td>所有工具都不启用</td></tr></tbody></table><p>例子：只读审查代码</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read,grep,find,ls,ast_grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;审查 src/ 下的代码，列出潜在的 bug&quot;</span></span></code></pre></div><p>不想让模型向你提问：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude-tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask_question</span></span></code></pre></div><h2 id="文件工具" tabindex="-1">文件工具 <a class="header-anchor" href="#文件工具" aria-label="Permalink to &quot;文件工具&quot;">​</a></h2><h3 id="read" tabindex="-1">read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;read {#read}&quot;">​</a></h3><p>读取文件，支持文本和图片（jpeg、png、gif、webp）。</p><ul><li>每行输出都带一个行号前缀，格式为六位右对齐的行号加一个竖线，例如 <code> 12|</code>。前缀不是文件内容的一部分。</li><li>不指定范围时，约 10,000 字符以内的文件完整返回。更大的<strong>源代码文件</strong>也会完整返回，但沿语法树折叠：10 行以上的函数、方法、类只显示首行、<code>...</code> 和末行，并保留真实行号。模型再用 <code>offset</code> 和 <code>limit</code> 读取折叠的部分。</li><li>没有代码大纲的语言（ast-grep 不支持的语言）按 50 行一块分段。</li><li><code>offset</code> 从 1 开始；负数表示从末尾倒数，<code>-1</code> 是最后一行。<code>limit</code> 限制行数。</li><li>输出超过 2000 行或 50KB 时截断，并提示从哪个 <code>offset</code> 继续。</li></ul><p>折叠用的代码大纲由 ast-grep 生成，所以 ast-grep 不可用时大文件只能分块读取。</p><h3 id="edit" tabindex="-1">edit <a class="header-anchor" href="#edit" aria-label="Permalink to &quot;edit {#edit}&quot;">​</a></h3><p>在文件里把一段精确的文本替换成新文本（参数 <code>file_path</code>、<code>old_string</code>、<code>new_string</code>、<code>replace_all</code>）。</p><ul><li><code>old_string</code> 必须与文件当前内容<strong>完全一致</strong>（包括缩进），并且在文件里<strong>只出现一次</strong>；需要替换所有出现时设置 <code>replace_all</code>。</li><li>行尾符会归一化后再匹配，所以 LF 写法也能匹配 CRLF 文件；写回时保留文件原来的编码、BOM 和行尾符。</li><li>写入是原子的（先写临时文件再替换）。</li><li>编辑前<strong>不要求</strong>先读文件：<code>old_string</code> 必须精确匹配这一约束本身就防止了基于过期内容的修改。</li><li>对同一个文件的多次 <code>edit</code> 按顺序执行，每次都基于上一次的结果。</li><li><code>old_string</code> 为空且文件不存在时，创建新文件。</li></ul><h3 id="write" tabindex="-1">write <a class="header-anchor" href="#write" aria-label="Permalink to &quot;write {#write}&quot;">​</a></h3><p>创建文件或整体覆盖已有文件，会自动创建父目录。</p><p><strong>覆盖已有文件前必须先读过它</strong>。以下都算“读过”：在当前分支上成功的 <code>read</code>、<code>edit</code>、<code>write</code>，以及识别得出的 shell 读取（<code>cat</code>、<code>head</code>、<code>tail</code>、<code>sed -n</code>，以及 PowerShell 的 <code>Get-Content</code>/<code>gc</code>/<code>cat</code>/<code>type</code> 读单个文件）。这个“已读”记录从会话分支重建，所以重启、<code>/resume</code>、<code>/fork</code> 之后仍然有效；用 <code>/tree</code> 切到没读过该文件的分支后需要重新读。</p><h2 id="搜索工具" tabindex="-1">搜索工具 <a class="header-anchor" href="#搜索工具" aria-label="Permalink to &quot;搜索工具&quot;">​</a></h2><h3 id="grep" tabindex="-1">grep <a class="header-anchor" href="#grep" aria-label="Permalink to &quot;grep {#grep}&quot;">​</a></h3><p>用 ripgrep 搜索文件内容。</p><ul><li><code>pattern</code> 是 Rust 正则；设置 <code>literal</code> 可以按字面文本搜索（适合包含 <code>(</code>、<code>[</code>、<code>.</code> 等字符的文本）。</li><li><code>path</code> 限定目录或文件，<code>glob</code> 过滤文件（例如 <code>*.ts</code>，或 <code>!**/*.test.ts</code> 排除）。</li><li><code>context</code> 显示匹配行前后的行，<code>ignoreCase</code> 忽略大小写。</li><li>遵守 <code>.gitignore</code>，包含点文件。</li><li>默认最多 100 条匹配或 50KB，单行超过 500 字符会截断。</li></ul><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to &quot;find {#find}&quot;">​</a></h3><p>按 glob 模式查找文件（基于 fd）。不含 <code>/</code> 的模式匹配任意层级的文件名（<code>*.ts</code>），含 <code>/</code> 的模式匹配相对路径（<code>src/**/*.test.ts</code>）。遵守 <code>.gitignore</code>，包含点文件，默认最多 1000 条结果。</p><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to &quot;ls {#ls}&quot;">​</a></h3><p>列出一个目录的内容，按字母排序，目录以 <code>/</code> 结尾，包含点文件，默认最多 500 条。</p><h3 id="ast-grep" tabindex="-1">ast_grep <a class="header-anchor" href="#ast-grep" aria-label="Permalink to &quot;ast_grep {#ast-grep}&quot;">​</a></h3><p>用 <a href="https://ast-grep.github.io/" target="_blank" rel="noreferrer">ast-grep</a> 按语法树结构搜索代码。适合找函数定义、某个 API 的所有调用、某种 import 写法等，比文本搜索更准确。</p><ul><li><code>pattern</code> 写成代码的样子，<code>$X</code> 匹配一个节点，<code>$$$X</code> 匹配零个或多个节点。例如 <code>console.log($$$ARGS)</code>、<code>function $NAME($$$) { $$$ }</code>。</li><li><code>lang</code> 指定语言（ts、tsx、js、py、go、rust 等），省略时按文件扩展名推断。</li><li><code>path</code> 限定文件或目录，<code>globs</code> 包含/排除文件。</li><li><code>strictness</code> 控制匹配严格程度：<code>cst</code>、<code>smart</code>（默认）、<code>ast</code>、<code>relaxed</code>、<code>signature</code>。</li><li>结果格式为 <code>路径:行号: 首行内容</code>，多行匹配会标注 <code>(+N lines)</code>。默认最多 100 条。</li></ul><h3 id="web-search" tabindex="-1">web_search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;web_search {#web-search}&quot;">​</a></h3><p>联网搜索，获取最新的公开信息。底层使用 Exa 托管的 MCP 服务，<strong>不需要 API key</strong>。</p><ul><li><code>query</code>：用自然语言描述要找的内容；</li><li><code>objective</code>：可选，说明搜索目的和偏好的来源；</li><li><code>num_results</code>：结果数，默认 8，最多 20；</li><li><code>allowed_domains</code> / <code>blocked_domains</code>：限定或排除域名。</li></ul><p>模型使用搜索结果时应在回答里列出来源链接。<code>web_search</code> 始终直接可用，不会被 <code>tool_search</code> 延迟加载。</p><h2 id="命令工具" tabindex="-1">命令工具 <a class="header-anchor" href="#命令工具" aria-label="Permalink to &quot;命令工具&quot;">​</a></h2><h3 id="bash" tabindex="-1">bash <a class="header-anchor" href="#bash" aria-label="Permalink to &quot;bash {#bash}&quot;">​</a></h3><p>执行 shell 命令，返回 stdout 和 stderr；退出码非零时作为错误报告并附上输出。</p><ul><li>默认没有超时，模型可以为可能挂起的命令设置 <code>timeout</code>（秒）。</li><li>输出只保留最后 2000 行或 50KB，完整输出保存到临时文件并给出路径。</li><li>每条命令在一个新的非交互 Bash 进程里执行：别名默认不展开，交互式 shell 的启动文件通常不会加载。需要别名或环境准备时用 <code>shellCommandPrefix</code>，见 <a href="/nekcode/platform/shell">Shell 命令配置</a>。</li><li>Windows 上默认使用 Git Bash。</li><li>命令能拿到当前会话的信息：<code>NEK_SESSION_ID</code>、<code>NEK_SESSION_FILE</code>、<code>NEK_PROVIDER</code>、<code>NEK_MODEL</code>、<code>NEK_REASONING_LEVEL</code>，见 <a href="/nekcode/reference/environment-variables#shell-env">环境变量</a>。</li></ul><h3 id="powershell" tabindex="-1">powershell <a class="header-anchor" href="#powershell" aria-label="Permalink to &quot;powershell {#powershell}&quot;">​</a></h3><p>只在原生 Windows 上可用，默认不启用。优先使用 PowerShell 7（<code>pwsh.exe</code>），没有时退回 Windows PowerShell，以 <code>-NoProfile -NonInteractive -ExecutionPolicy Bypass</code> 启动。启用方法见 <a href="/nekcode/platform/windows#powershell">在 Windows 上运行</a>。</p><h2 id="规划与协作工具" tabindex="-1">规划与协作工具 <a class="header-anchor" href="#规划与协作工具" aria-label="Permalink to &quot;规划与协作工具&quot;">​</a></h2><p>这些工具由 nek 扩展提供。</p><table tabindex="0"><thead><tr><th>工具</th><th>作用</th><th>详见</th></tr></thead><tbody><tr><td><code>todo_write</code></td><td>创建和更新输入框上方的 Todo 列表</td><td><a href="/nekcode/guide/todos">Todo 列表</a></td></tr><tr><td><code>switch_mode</code></td><td>提议在 Agent 和 Plan 模式之间切换，需要你确认</td><td><a href="/nekcode/guide/plan-mode#switch-mode">Plan 模式</a></td></tr><tr><td><code>create_plan</code></td><td>Plan 模式下保存一份新计划（或整份重写），并提交你审阅</td><td><a href="/nekcode/guide/plan-mode">Plan 模式</a></td></tr><tr><td><code>update_plan</code></td><td>Plan 模式下，在模型用 <code>edit</code> 增量修改计划文件后提交审阅</td><td><a href="/nekcode/guide/plan-mode#revise">Plan 模式</a></td></tr><tr><td><code>ask_question</code></td><td>向你提出多选题</td><td>见下文</td></tr><tr><td><code>subagent</code></td><td>把一个边界清晰的任务派给子代理，前台或后台运行</td><td><a href="/nekcode/guide/subagents">子代理</a></td></tr><tr><td><code>await</code></td><td>等待后台子代理完成</td><td><a href="/nekcode/guide/subagents#await">子代理</a></td></tr></tbody></table><h3 id="ask-question" tabindex="-1">ask_question <a class="header-anchor" href="#ask-question" aria-label="Permalink to &quot;ask_question {#ask-question}&quot;">​</a></h3><p>模型遇到只能由你决定的问题时（例如选哪个库、哪种数据模型），会弹出多选题而不是用大段文字追问。</p><ul><li>每次 1~2 个问题，每个问题至少两个选项；</li><li>可以允许多选；</li><li>始终可以选 <strong>Other</strong> 输入自己的答案（在原位换行编辑）；</li><li>推荐项排在第一个，并标注 <code>(Recommended)</code>。</li></ul><p>这个调用会<strong>阻塞</strong>，直到你回答。nek 的提示词要求模型只在真正需要你决定时才提问：可逆的、范围内的操作直接做，提交、跑测试这类例行流程按项目指令自行决定。不希望被打断时可以用 <code>--exclude-tools ask_question</code> 禁用。</p><h2 id="tool-search" tabindex="-1">按需加载：tool_search <a class="header-anchor" href="#tool-search" aria-label="Permalink to &quot;按需加载：tool_search {#tool-search}&quot;">​</a></h2><p>有些工具注册了但默认不声明给模型（<strong>deferred</strong>，延迟加载），例如 MCP 服务器的工具。这样首次请求不会因为几十个 MCP 工具而变得臃肿。</p><p><code>tool_search</code> 只在存在可发现的延迟工具（或仍在连接的延迟工具来源）时出现。模型用它按名字、描述、参数做 BM25 搜索，匹配到的工具会在下一次请求时激活，之后就能直接调用。加载记录保存在会话分支上，续接、<code>/tree</code>、<code>/fork</code> 后依然有效。</p><p>工具的四种暴露方式：</p><table tabindex="0"><thead><tr><th>暴露方式</th><th>行为</th></tr></thead><tbody><tr><td><code>direct</code>（默认）</td><td>像内置工具一样直接声明</td></tr><tr><td><code>model-only</code></td><td>在 nek 中等同 <code>direct</code></td></tr><tr><td><code>deferred</code></td><td>注册但不激活，通过 <code>tool_search</code> 加载</td></tr><tr><td><code>hidden</code></td><td>注册但永不声明、不可发现、不可激活</td></tr></tbody></table><p>MCP 工具的暴露方式配置见 <a href="/nekcode/guide/mcp#exposure">MCP 服务器</a>。</p><h2 id="mcp-资源工具" tabindex="-1">MCP 资源工具 <a class="header-anchor" href="#mcp-资源工具" aria-label="Permalink to &quot;MCP 资源工具&quot;">​</a></h2><p>连接的 MCP 服务器提供资源时，会额外出现 <code>list_mcp_resources</code>、<code>list_mcp_resource_templates</code>、<code>read_mcp_resource</code>，见 <a href="/nekcode/guide/mcp#resources">MCP 服务器</a>。</p><h2 id="工具与安全" tabindex="-1">工具与安全 <a class="header-anchor" href="#工具与安全" aria-label="Permalink to &quot;工具与安全&quot;">​</a></h2><p>所有工具都以 nek 进程的操作系统权限运行。工作目录只决定默认路径，不阻止命令访问其他路径。项目信任只控制加载哪些项目资源，不限制工具能做什么。见 <a href="/nekcode/guide/security">安全使用</a>。</p>',61)])])}const b=o(c,[["render",l]]);export{u as __pageData,b as default};
